using System;
using System.Collections;
using System.Collections.Generic;
using System.Linq;
using System.Web.Script.Serialization;
using RogControlNotebook;

public static class NotebookControlTests {
 static int checks;
 static void Check(bool value,string label){checks++;if(!value)throw new Exception("case "+checks+": "+label);}
 static readonly JavaScriptSerializer Json=new JavaScriptSerializer();
 static Dictionary<string,object> Obj(params object[] values){return NotebookRules.Obj(values);}
 static Dictionary<string,object> Map(Dictionary<string,object> value,string key){return (Dictionary<string,object>)value[key];}
 sealed class Fake:INotebookControlTransport {
  public int Identities,Opens,Reads,Writes,Disposals;public long Clock;public bool ThrowWrite,ThrowRead;public uint Acknowledgement=1;public Action<Fake,uint> OnRead;public Action<Fake> OnIdentity,OnWrite;
  public NotebookIdentity Identity=new NotebookIdentity{Manufacturer="ASUSTeK COMPUTER INC.",Model="ROG GU605MI_GU605MI",ChassisTypes=new[]{10},IdentityReadConfirmed=true,InterfaceDriverConfirmed=true,AcOnline=true,InterfaceDrivers=new List<object>{Obj("name","ASUS System Control Interface V3","provider","ASUSTeK COMPUTER INC.","version","3.1.70.0","signed",true)}};
  public readonly Dictionary<uint,byte[]> Responses=new Dictionary<uint,byte[]>{{0x00120075,BitConverter.GetBytes(0x10000u)},{0x00120057,BitConverter.GetBytes(0x10050u)},{0x00050021,BitConverter.GetBytes(0x10382u)},{0x00050019,BitConverter.GetBytes(0x10000u)},{0x00090020,BitConverter.GetBytes(0x10000u)},{0x00090016,BitConverter.GetBytes(0x10001u)},{0x00050020,BitConverter.GetBytes(0x10001u)},{0x00090019,BitConverter.GetBytes(0xFFFFFFFEu)},{0x00090030,BitConverter.GetBytes(0x10000u)}};
  public readonly List<byte[]> Packets=new List<byte[]>();
  public NotebookService Service;
  public Fake(){Service=new NotebookService(()=>{Identities++;if(OnIdentity!=null)OnIdentity(this);return Identity;},()=>{Opens++;return this;},8000,()=>Clock);}
  public byte[] ReadStatus(uint endpoint){Reads++;if(OnRead!=null)OnRead(this,endpoint);if(ThrowRead)throw new InvalidOperationException("FAKE_IO");return (byte[])Responses[endpoint].Clone();}
  public byte[] WriteControl(uint endpoint,uint parameter){Writes++;Packets.Add(NotebookControlRules.Packet(endpoint,parameter));if(OnWrite!=null)OnWrite(this);if(ThrowWrite)throw new InvalidOperationException("FAKE_IO");if(endpoint==0x50021)Responses[endpoint]=BitConverter.GetBytes(0x10300u|parameter);return BitConverter.GetBytes(Acknowledgement);}
  public void Dispose(){Disposals++;}
  public Dictionary<string,object> Request(Dictionary<string,object> value){return Json.Deserialize<Dictionary<string,object>>(Service.HandleLine(Json.Serialize(value)));}
  public Dictionary<string,object> Capture(){var reply=Request(Obj("op","controlRead"));Check(Object.Equals(reply["ok"],true),"fake control capture succeeded");return Map(reply,"data");}
  public Dictionary<string,object> Command(Dictionary<string,object> capture,string setting,int value){return Obj("op","set","setting",setting,"value",value,"experimental",true,"modelCode",capture["modelCode"],"identityToken",capture["controlIdentityToken"],"sessionToken",capture["controlSessionToken"],"readToken",capture["controlReadToken"],"acceptDisplayDisruption",true,"acceptReboot",true);}
 }
 static Dictionary<string,object> Cap(Dictionary<string,object> data,string name){return ((IEnumerable)data["controlStates"]).Cast<Dictionary<string,object>>().Single(s=>(string)s["feature"]==name);}
 static int[] Values(Dictionary<string,object> cap){return ((IEnumerable)cap["allowedValues"]).Cast<object>().Select(Convert.ToInt32).ToArray();}
 static void Error(Dictionary<string,object> reply,string code){Check(Object.Equals(reply["ok"],false)&&(string)Map(reply,"error")["code"]==code,"expected fail-closed error "+code);}
 static void Golden(){
  var cases=new[]{Tuple.Create("performanceMode",1,new byte[]{68,69,86,83,8,0,0,0,117,0,18,0,1,0,0,0}),Tuple.Create("chargeLimit",80,new byte[]{68,69,86,83,8,0,0,0,87,0,18,0,80,0,0,0}),Tuple.Create("keyboardBrightness",0,new byte[]{68,69,86,83,8,0,0,0,33,0,5,0,128,0,0,0}),Tuple.Create("displayOverdrive",1,new byte[]{68,69,86,83,8,0,0,0,25,0,5,0,1,0,0,0}),Tuple.Create("gpuEco",1,new byte[]{68,69,86,83,8,0,0,0,32,0,9,0,1,0,0,0}),Tuple.Create("gpuMux",0,new byte[]{68,69,86,83,8,0,0,0,22,0,9,0,0,0,0,0})};
  foreach(var item in cases){var fake=new Fake();var capture=fake.Capture();var reply=fake.Request(fake.Command(capture,item.Item1,item.Item2));Check(Object.Equals(reply["ok"],true)&&fake.Writes==1&&fake.Packets.Single().SequenceEqual(item.Item3),"fixed independent golden DEVS packet "+item.Item1);var data=Map(reply,"data");Check(Object.Equals(data["restorable"],false),"no invented automatic restore "+item.Item1);Check((string)data["appliedState"]==(item.Item1=="keyboardBrightness"?"confirmed":"submittedUnconfirmed"),"acknowledgement is not invented setting confirmation "+item.Item1);Check((bool)data["writeConfirmed"]==(item.Item1=="keyboardBrightness"),"only real brightness decoder confirms a current value "+item.Item1);Error(fake.Request(fake.Command(capture,item.Item1,item.Item2)),"STALE_CAPTURE");Check(fake.Writes==1,"single-use capture cannot write twice");}
  foreach(var spec in NotebookControlRules.Specs)foreach(int value in new[]{spec.Minimum,spec.Maximum}){var packet=NotebookControlRules.Packet(spec.Endpoint,spec.Parameter(value));Check(packet.Length==16&&packet.Take(8).SequenceEqual(new byte[]{68,69,86,83,8,0,0,0}),"fixed method and argument size at legal boundary");}
  foreach(uint endpoint in new uint[]{0,0x00110024,0x00050020,0x00090030,UInt32.MaxValue}){bool blocked=false;try{NotebookControlRules.Packet(endpoint,1);}catch(ArgumentException){blocked=true;}Check(blocked,"read-only/arbitrary endpoint cannot encode DEVS");}
  var zero=NotebookControlRules.Decode(0x50021,BitConverter.GetBytes(0x10380u));Check(zero.Presence&&zero.CurrentValue==0,"confirmed backlight-off zero remains valid");
 }
 static void IdentityAndSchema(){
  foreach(Action<Fake> damage in new Action<Fake>[] {f=>f.Identity.Manufacturer="Other ASUS",f=>f.Identity.Model="GU605MIX",f=>f.Identity.Model="GU605MI RC71L",f=>f.Identity.Model="Unknown ASUS mobile",f=>f.Identity.ChassisTypes=new[]{3},f=>f.Identity.ChassisTypes=new int[0],f=>f.Identity.ChassisTypes=new[]{10,3},f=>f.Identity.IdentityReadConfirmed=false,f=>f.Identity.InterfaceDriverConfirmed=false,f=>f.Identity.InterfaceDrivers.Clear(),f=>((Dictionary<string,object>)f.Identity.InterfaceDrivers[0])["signed"]=false,f=>((Dictionary<string,object>)f.Identity.InterfaceDrivers[0])["provider"]="Other",f=>((Dictionary<string,object>)f.Identity.InterfaceDrivers[0])["version"]="unknown"}){var fake=new Fake();damage(fake);var result=fake.Capture();Check(fake.Opens==0&&fake.Reads==0&&fake.Writes==0&&!(bool)result["supportsWrite"],"unconfirmed identity/driver stays identity only without native interface");}
  foreach(string key in new[]{"endpoint","methodId","raw","status","model","driver"}){var fake=new Fake();Error(fake.Request(Obj("op","controlRead",key,1)),"INVALID_REQUEST");Check(fake.Identities==0&&fake.Opens==0,"caller protocol override rejected before I/O");}
  foreach(object invalid in new object[]{null,"80",80.5,true,-1,39,101}){var fake=new Fake();var capture=fake.Capture();int prior=fake.Identities;var command=fake.Command(capture,"chargeLimit",80);command["value"]=invalid;Error(fake.Request(command),"INVALID_REQUEST");Check(fake.Identities==prior&&fake.Writes==0,"typed charge bounds validated before identity I/O");}
  foreach(object flag in new object[]{null,false,"true",1}){var fake=new Fake();var capture=fake.Capture();int prior=fake.Identities;var command=fake.Command(capture,"chargeLimit",80);command["experimental"]=flag;Error(fake.Request(command),"CONTROL_DISABLED");Check(fake.Identities==prior&&fake.Writes==0,"explicit permission before any control I/O");}
  var first=new Fake();var old=first.Capture();var other=new Fake();Error(other.Request(other.Command(old,"chargeLimit",80)),"STALE_CAPTURE");Check(other.Writes==0,"new worker process does not adopt old lease");
  foreach(string key in new[]{"sessionToken","readToken","identityToken","modelCode"}){var fake=new Fake();var capture=fake.Capture();var command=fake.Command(capture,"chargeLimit",80);command[key]=key=="identityToken"?new string('f',64):key=="modelCode"?"GA402RJ":new string('f',32);Error(fake.Request(command),"STALE_CAPTURE");Check(fake.Writes==0,"foreign capture key cannot apply "+key);}
  var handheld=new Fake();handheld.Identity.Model="RC72LA";handheld.Identity.ChassisTypes=new[]{11};var ally=handheld.Capture();Check(((IEnumerable)ally["controlStates"]).Cast<object>().Count()==2&&handheld.Reads==2,"handheld probes only shared mode and charging endpoints");Error(handheld.Request(handheld.Command(ally,"keyboardBrightness",1)),"CONTROL_UNSUPPORTED");Check(handheld.Writes==0,"handheld cannot use notebook-only keyboard control");
 }
 static void PresenceAndGuards(){
  foreach(uint raw in new uint[]{0,1,0xFFFFFFFE,0xFFFFFFFF,0x80010001,0x100FF}){var fake=new Fake();fake.Responses[0x120075]=BitConverter.GetBytes(raw);var cap=Cap(fake.Capture(),"performanceMode");Check(!(bool)cap["writeSupported"],"nonzero/unsupported/range flags never stand in for endpoint support");}
  var presentZero=new Fake();Check((bool)Cap(presentZero.Capture(),"performanceMode")["writeSupported"],"presence-flagged zero supports legal mode values");
  foreach(bool? ac in new bool?[]{false,null}){var fake=new Fake();fake.Identity.AcOnline=ac;var capture=fake.Capture();Check(!Values(Cap(capture,"performanceMode")).Contains(1)&&Values(Cap(capture,"performanceMode")).SequenceEqual(new[]{0,2}),"turbo excluded on battery or unknown AC");Error(fake.Request(fake.Command(capture,"performanceMode",1)),"CONTROL_UNSUPPORTED");Check(fake.Writes==0,"turbo guard is enforced at worker boundary");}
  foreach(uint support in new uint[]{0,1,0x10000,0xFFFFFFFF,0x80010001}){var fake=new Fake();fake.Responses[0x50020]=BitConverter.GetBytes(support);Check(!(bool)Cap(fake.Capture(),"displayOverdrive")["writeSupported"],"Overdrive requires separate present supported=1 endpoint");}
  foreach(uint raw in new uint[]{0x10000,0x10001,0xFFFFFFFE,0}){var fake=new Fake();fake.Responses[0x90016]=BitConverter.GetBytes(raw);var cap=Cap(fake.Capture(),"gpuEco");Check(Values(cap).Contains(1)==(raw==0x10001),"Eco disable requires verified hybrid MUX state");}
  foreach(uint endpoint in new uint[]{0x90030,0x90019})foreach(uint raw in new uint[]{0,0x10001}){var fake=new Fake();fake.Responses[endpoint]=BitConverter.GetBytes(raw);var capture=fake.Capture();Check(!Values(Cap(capture,"gpuEco")).Contains(1)&&!Values(Cap(capture,"gpuMux")).Contains(0),"unknown/active external graphics blocks disruptive GPU values");}
  foreach(string key in new[]{"acceptDisplayDisruption","acceptReboot"}){var fake=new Fake();var capture=fake.Capture();var command=fake.Command(capture,"gpuMux",0);command[key]=false;Error(fake.Request(command),"CONTROL_ACK_REQUIRED");Check(fake.Writes==0,"MUX has explicit user acknowledgement guard");}
 }
 static void RacesDeadlinesAndResults(){
  var expired=new Fake();var capture=expired.Capture();expired.Clock=30000;Error(expired.Request(expired.Command(capture,"chargeLimit",80)),"STALE_CAPTURE");Check(expired.Writes==0,"30s lease expiry prevents command");
  var clockBack=new Fake();capture=clockBack.Capture();clockBack.Clock=-1;Error(clockBack.Request(clockBack.Command(capture,"chargeLimit",80)),"STALE_CAPTURE");Check(clockBack.Writes==0,"negative lease age prevents command");
  var driver=new Fake();capture=driver.Capture();((Dictionary<string,object>)driver.Identity.InterfaceDrivers[0])["version"]="3.1.71.0";Error(driver.Request(driver.Command(capture,"chargeLimit",80)),"IDENTITY_CHANGED");Check(driver.Writes==0,"driver generation change prevents command");
  var status=new Fake();capture=status.Capture();status.Responses[0x120057]=BitConverter.GetBytes(0x10051u);Error(status.Request(status.Command(capture,"chargeLimit",80)),"STALE_CAPTURE");Check(status.Writes==0,"fresh status race cannot overwrite captured draft");
  var before=new Fake();capture=before.Capture();before.OnIdentity=f=>{if(f.Identities==4)f.Identity.Model="GA402RJ";};Error(before.Request(before.Command(capture,"chargeLimit",80)),"IDENTITY_CHANGED");Check(before.Writes==0,"identity rechecked immediately before DEVS");
  var late=new Fake();capture=late.Capture();late.OnRead=(f,e)=>f.Clock=8000;Error(late.Request(late.Command(capture,"chargeLimit",80)),"QUERY_TIMEOUT");Check(late.Writes==0&&late.Service.RestartRequired,"deadline-crossing preflight quarantines before write");
  var denied=new Fake();capture=denied.Capture();denied.ThrowWrite=true;var result=Map(denied.Request(denied.Command(capture,"chargeLimit",80)),"data");Check((bool)result["writeAttempted"]&&!(bool)result["writeConfirmed"]&&(string)result["appliedState"]=="writeEffectUnknown"&&denied.Writes==1,"write failure is explicit unknown effect, never automatic retry or restore");
  foreach(uint ack in new uint[]{0,1,2,0xFFFFFFFE,UInt32.MaxValue}){var fake=new Fake{Acknowledgement=ack};capture=fake.Capture();result=Map(fake.Request(fake.Command(capture,"chargeLimit",80)),"data");Check(!(bool)result["writeConfirmed"]&&(string)result["appliedState"]==(ack<=1?"submittedUnconfirmed":"writeEffectUnknown"),"native-status setting does not fabricate confirmation from ACK "+ack);Check(fake.Writes==1&&!fake.Packets.Any(p=>BitConverter.ToUInt32(p,0)!=0x53564544),"single fixed submission with no recovery/init "+ack);}
  var noOp=new Fake();capture=noOp.Capture();result=Map(noOp.Request(noOp.Command(capture,"keyboardBrightness",2)),"data");Check(noOp.Writes==0&&!(bool)result["writeAttempted"]&&(bool)result["writeConfirmed"]&&(string)result["appliedState"]=="alreadySet","brightness true current-value same-value NoOp has no DEVS");
  var failedReadback=new Fake();capture=failedReadback.Capture();failedReadback.OnWrite=f=>f.ThrowRead=true;result=Map(failedReadback.Request(failedReadback.Command(capture,"keyboardBrightness",1)),"data");Check(!(bool)result["writeConfirmed"]&&(string)result["appliedState"]=="submittedUnconfirmed"&&failedReadback.Writes==1,"readback failure never announces success or starts a restore");
  var after=new Fake();capture=after.Capture();after.OnWrite=f=>f.Identity.Model="GA402RJ";result=Map(after.Request(after.Command(capture,"chargeLimit",80)),"data");Check((string)result["appliedState"]=="writeEffectUnknown"&&!(bool)result["writeConfirmed"],"identity change after submission cannot produce confirmed outcome");
 }
 public static int Main(){try{Golden();IdentityAndSchema();PresenceAndGuards();RacesDeadlinesAndResults();Console.WriteLine("Notebook SCI control: "+checks+" pure checks; WMI/ATKACPI/native/GUI=0.");return 0;}catch(Exception error){Console.Error.WriteLine(error.GetType().Name+": "+error.Message);return 1;}}
}
